from pathlib import Path
import json,shutil
D=Path('KiCad-RevE'); E=Path('engineering'); d=json.loads((D/'reports/power-trial-drc.json').read_text()); assert not d['violations'] and not d['unconnected_items']
backup=D/'before-c11-local-gvdd.kicad_pcb'; assert not backup.exists(); shutil.copy2(D/'PoE-Speaker-RevE.kicad_pcb',backup); shutil.copy2(D/'power-trial.kicad_pcb',D/'PoE-Speaker-RevE.kicad_pcb')
f=E/'revision-e-design.json'; m=json.loads(f.read_text()); m['components']['C11'].update(position=[204.9,111.5],angle=270.0,side='Bottom'); f.write_text(json.dumps(m,indent=2)+'\n')
f=E/'package_prototype_review.py'; s=f.read_text(); s=s.replace('Next: review the C11 GVDD bypass using reports/amplifier-decoupling-audit.json and the detailed rejected-trial notes in engineering/REVE-TRUNK-ROUTING.md. C11 has NOT moved; power-trial is unaccepted. Preserve the R15 PLIMIT branch.', 'Next: continue amplifier supply/ground-return review using reports/amplifier-decoupling-audit.json. C11 is accepted on B.Cu at (204.9,111.5), angle 270, with a local GVDD connection and a separate ground via. The R15 PLIMIT branch is preserved. Five obsolete C11 spur items were removed; see engineering/REVE-TRUNK-ROUTING.md.'); s=s.replace('Saved changes: U7', 'Saved changes: C11 GVDD bypass is now local on B.Cu at (204.9,111.5), preserving the R15 PLIMIT branch; underside assembly clearance remains part of mechanical review. U7'); f.write_text(s)
f=E/'prune_c11_old_spur.py'; f.write_text(f.read_text().replace('dangling AMP_SW_NEG copper','dangling AMP_GVDD/GND copper'))
with (E/'REVE-TRUNK-ROUTING.md').open('a',encoding='utf-8') as f:f.write('\n\n## Accepted C11 local GVDD bypass — 2026-09-14\n\nMapped the actual bottom-layer corridor before placement. C11 moved from top (210,120), 180 degrees, to bottom (204.9,111.5), 270 degrees. Its GVDD pad connects locally to the existing GVDD via at (205.583,110.37); ground bends left around the MUTE via, then reaches a new 0.5 mm diameter / 0.3 mm drill ground via at (205.2,114.1). Retained the full R15 PLIMIT branch. Removed five DRC-identified obsolete C11 spur items. Trial DRC: zero findings and zero unconnected items. Bottom copper/silkscreen render inspected. Main pre-change backup: before-c11-local-gvdd.kicad_pcb. This supersedes earlier rejected C11 trials. Current/return-plane and assembly qualification remain pending; no fabrication release.\n')
